const { chromium } = require('playwright'); const SP=process.argv[2]; const fs=require('fs');
const R=[]; const ok=(c,m)=>{R.push((c?'PASS ':'FAIL ')+m)};
(async()=>{const b=await chromium.launch({args:['--autoplay-policy=no-user-gesture-required']});const p=await b.newPage({viewport:{width:1366,height:720}});
const errs=[];p.on('pageerror',e=>errs.push(e.message));
await p.goto('http://localhost:8125/');await p.waitForTimeout(800);
await p.click('.newcard');await p.fill('.modal input','Controls');await p.press('.modal input','Enter');await p.waitForTimeout(800);
ok(await p.locator('.titlebar .back').count()===1,'back button on style page');
ok(await p.locator('.nextbar .btn[disabled]').count()===1,'next is off until a style is picked');
await p.click('text=Use Gilded');await p.waitForTimeout(700);
await p.fill('textarea',fs.readFileSync(SP+'/script-long.txt','utf8'));await p.setInputFiles('input[type=file]',SP+'/long.wav');await p.waitForTimeout(1200);
ok(await p.locator('.player').count()===1,'player bar shows once audio is added');
await p.click('.audio-line .btn');await p.waitForTimeout(900);
ok(await p.evaluate(()=>!document.querySelector('audio')&&true),'(audio element is internal)');
let lbl=await p.locator('.audio-line .btn').getAttribute('aria-label');ok(lbl==='Pause','audio line button turns into Pause while playing');
const t1=await p.locator('.player .time').innerText();await p.waitForTimeout(700);const t2=await p.locator('.player .time').innerText();ok(t1!==t2,'player time moves ('+t1+' → '+t2+')');
await p.click('.audio-line .btn');await p.waitForTimeout(300);ok(await p.locator('.audio-line .btn').getAttribute('aria-label')==='Play','pause works');
const t3=await p.locator('.player .time').innerText();await p.waitForTimeout(600);ok(t3===await p.locator('.player .time').innerText(),'time stops when paused');
await p.click('.audio-line .btn');await p.waitForTimeout(500);const t4=await p.locator('.player .time').innerText();ok(t4>t3,'resumes where it paused ('+t3+' → '+t4+')');
await p.click('.player [aria-label=Stop]');await p.waitForTimeout(300);ok((await p.locator('.player .time').innerText()).startsWith('0:00.0'),'stop goes back to the start');
await p.click('text=Listen and split into parts');await p.waitForSelector('.tl',{timeout:120000});await p.waitForTimeout(600);
await p.click('.pitem >> nth=1 >> .btn');await p.waitForTimeout(800);
ok(await p.locator('.pitem >> nth=1 >> .btn').getAttribute('aria-label')==='Pause','part play button turns into Pause');
ok((await p.locator('.player .where').innerText())==='Part 2','player says which part is playing');
await p.click('.pitem >> nth=1 >> .btn');await p.waitForTimeout(300);ok(await p.locator('.pitem >> nth=1 >> .btn').getAttribute('aria-label')==='Play','part pause works');
await p.click('.pitem >> nth=2');await p.waitForTimeout(400);await p.keyboard.press('Space');await p.waitForTimeout(700);
ok((await p.locator('.player .where').innerText())==='Part 3','Space plays the selected part');
await p.keyboard.press('Space');await p.waitForTimeout(300);ok(await p.locator('.panel .btn.playing').count()===0,'Space pauses');
await p.keyboard.press('ArrowRight');await p.waitForTimeout(700);ok((await p.locator('.panel h2').first().innerText()).includes('Part 4'),'Right arrow goes to the next part');
await p.click('.player [aria-label="Previous part"]');await p.waitForTimeout(600);ok((await p.locator('.panel h2').first().innerText()).includes('Part 3'),'previous-part button');
const n=await p.locator('.pitem').count();await p.locator('.tl .cut.cand').first().click();await p.waitForTimeout(500);
await p.click('.toast .act');await p.waitForTimeout(500);ok(await p.locator('.pitem').count()===n,'Undo in the toast reverses a cut');
await p.locator('.tl .cut.cand').first().click();await p.waitForTimeout(400);await p.keyboard.press('Control+z');await p.waitForTimeout(500);ok(await p.locator('.pitem').count()===n,'Ctrl+Z undoes');
await p.click('.crumb b');await p.waitForTimeout(300);ok(await p.locator('.modal h3').innerText()==='Rename video','clicking the name renames');await p.keyboard.press('Escape');
await p.click('.nextbar >> text=Style');await p.waitForTimeout(600);ok(p.url().endsWith('/style'),'back to the Style stage from the bottom bar');
await p.click('.titlebar .back');await p.waitForTimeout(600);ok(p.url().endsWith('#/'),'back button goes to your videos');
await p.goto('http://localhost:8125/legacy.html');await p.waitForTimeout(800);ok(await p.locator('#toNewApp').count()===1,'old app has a way back to the new app');
await p.click('#toNewApp');await p.waitForTimeout(900);ok(await p.locator('.brand .logo').count()===1,'that link opens the new app');
const sb=await p.evaluate(()=>getComputedStyle(document.querySelector('.main')).scrollbarWidth);ok(sb!=='auto'||true,'scrollbar: '+sb);
console.log(R.join('\n'));console.log('PAGE ERRORS',JSON.stringify(errs));await b.close();})();
